function findHeuristic(issue) {
  const map = {
    spinner: "visibility of status",
    undo: "user control",
    jargon: "match with the real world",
    confirm: "error prevention"
  };
  for (const key in map) {
    if (issue.includes(key)) return map[key];
  }
  return "unknown";
}
console.log(findHeuristic("no confirm before delete"));

